const out = rows(TABLE).map(([code, q, a, ds, fact]) => {
  const t = TOPIC[code];
  if (!t) throw new Error('Unknown topic code ' + code);
  return { s: 'general', t, q, a, d: ds.split(';').map((x) => x.trim()), e: `${fact}\nSo the answer is ==${a}==.` };
});

module.exports = out;
